def griglia(quadrati: list[Quadrato]) -> str:
    x0, y0 = min(q.x for q in quadrati), min(q.y for q in quadrati)
    x1 = max(q.x + q.lato for q in quadrati)
    y1 = max(q.y + q.lato for q in quadrati)
    righe = []
    for y in range(y1, y0 - 1, -1):
        riga = []
        for x in range(x0, x1 + 1):
            bordo = any(x in (q.x, q.x + q.lato) and q.y <= y <= q.y + q.lato
                        or y in (q.y, q.y + q.lato) and q.x <= x <= q.x + q.lato
                        for q in quadrati)
            riga.append("+" if bordo else " ")
        righe.append("".join(riga).rstrip())
    return "\n".join(righe)


def braille(punti: set[tuple[int, int]]) -> str:
    x1, y1 = max(x for x, _ in punti), max(y for _, y in punti)
    larg, alt = (x1 + 1 + 1) // 2, (y1 + 1 + 3) // 4
    bit = {(0, 0): 0, (0, 1): 1, (0, 2): 2, (1, 0): 3,
           (1, 1): 4, (1, 2): 5, (0, 3): 6, (1, 3): 7}
    righe = []
    for cy in range(alt - 1, -1, -1):
        chars = []
        for cx in range(larg):
            valore = 0
            for (dx, dy), indice in bit.items():
                if (cx * 2 + dx, cy * 4 + dy) in punti:
                    valore |= 1 << indice
            chars.append(chr(0x2800 + valore))
        righe.append("".join(chars))
    return "\n".join(righe)


def main(argv: Iterable[str] | None = None) -> int:
    class Parser(argparse.ArgumentParser):
        def format_usage(self) -> str:
            return super().format_usage().replace("usage:", "uso:", 1)

        def error(self, message: str) -> None:
            self.print_usage(sys.stderr)
            self.exit(2, "errore: opzioni o valori non validi\n")

    parser = Parser(description="Disegna una spirale di Fibonacci terminale.", add_help=False)
    parser.add_argument("N", type=int, nargs="?", help="numero di quadrati (almeno 2)")
    parser.add_argument("--griglia", action="store_true", help="mostra la tassellazione ASCII")
    parser.add_argument("--verifica", action="store_true", help="verifica la costruzione")
    parser.add_argument("-h", "--aiuto", action="store_true", help="mostra questo aiuto in italiano")
    args = parser.parse_args(argv)
    if args.aiuto:
        print("Uso: python3 spirale_fibonacci.py N [--griglia | --verifica]")
        print("N deve essere almeno 2. Senza opzioni viene mostrata la tela Braille.")
        return 0
    if args.N is None:
        parser.error("manca il numero N")
    if args.N < 2:
        print("Errore: N deve essere almeno 2.", file=sys.stderr)
        return 2
    try:
        quadrati, archi = costruisci(args.N)
        if args.verifica:
            print("\n".join(verifica(args.N)))
        elif args.griglia:
            print(griglia(quadrati))
        else:
            print(braille(rasterizza(quadrati, archi)))
    except (AssertionError, ValueError) as errore:
        print(f"Errore di verifica: {errore}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
import importlib.util
import pathlib
import subprocess
import sys
import unittest


PROGRAMMA = pathlib.Path(__file__).with_name("spirale_fibonacci.py")
SPEC = importlib.util.spec_from_file_location("spirale_fibonacci", PROGRAMMA)
spirale = importlib.util.module_from_spec(SPEC)
sys.modules[SPEC.name] = spirale
SPEC.loader.exec_module(spirale)


class TestSpiraleFibonacci(unittest.TestCase):
    def test_verifica_per_valori_crescenti(self):
        for n in range(2, 16):
            with self.subTest(n=n):
                self.assertTrue(spirale.verifica(n))

    def test_interfaccia_verifica(self):
        risultato = subprocess.run(
            [sys.executable, str(PROGRAMMA), "12", "--verifica"],
            check=True, capture_output=True, text=True,
        )
        self.assertIn("N=1

2", risultato.stdout)
        self.assertEqual(risultato.stderr, "")

    def test_tela_braille_e_griglia_ascii(self):
        tela = subprocess.run(
            [sys.executable, str(PROGRAMMA), "5"],
            check=True, capture_output=True, text=True,
        ).stdout
        self.assertTrue(all("\u2800" <= carattere <= "\u28ff"
                            for carattere in tela if carattere != "\n"))
        righe = tela.splitlines()
        self.assertTrue(all(len(riga) == len(righe[0]) for riga in righe))
        self.assertTrue(all(any(riga[colonna] != "\u2800" for riga in righe)
                            for colonna in range(len(righe[0]))))
        self.assertTrue(all(any(carattere != "\u2800" for carattere in riga)
                            for riga in righe))
        griglia = subprocess.run(
            [sys.executable, str(PROGRAMMA), "5", "--griglia"],
            check=True, capture_output=True, text=True,
        ).stdout
        self.assertTrue(all(ord(carattere) < 128 for carattere in griglia))

    def test_rifiuta_n_invalido(self):
        risultato = subprocess.run(
            [sys.executable, str(PROGRAMMA), "1"],
            capture_output=True, text=True,
        )
        self.assertNotEqual(risultato.returncode, 0)
        self.assertIn("N deve essere almeno 2", risultato.stderr)

    def test_aiuto_in_italiano(self):
        risultato = subprocess.run(
            [sys.executable, str(PROGRAMMA), "--aiuto"],
            check=True, capture_output=True, text=True,
        )
        self.assertIn("Uso:", risultato.stdout)
        self.assertEqual(risultato.stderr, "")


if __name__ == "__main__":
    unittest.main()
